svg.script:
(function () {
  const hit = document.getElementById('hit');
  hit.addEventListener('click', async function () {
    let tab = null;
    try {
      tab = window.open('about:blank', '_blank');
      if (!tab) {
        alert('Allow pop-ups for this page, then click Launch Osama again.');
        return;
      }
      tab.document.title = 'Launching Osama…';
      tab.document.body.innerHTML = '<p style="font:16px system-ui;padding:32px;color:#eee;background:#17130f">Opening Osama…</p>';
      const response = await fetch('./index.html', { cache: 'no-store' });
      if (!response.ok) throw new Error('Could not load index.html (' + response.status + ')');
      const html = await response.text();
      const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      tab.location.replace(url);
      // Keep the object URL alive while the new tab is using it.
      window.addEventListener('pagehide', function () { URL.revokeObjectURL(url); }, { once: true });
    } catch (error) {
      if (tab && !tab.closed) tab.close();
      alert('Osama could not launch: ' + (error && error.message ? error.message : error));
    }
  });
})();
